//! Deterministic CB-F1 compact-flat and exact-factored artifact packer.
//!
//! The format is intentionally small and closed: every integer is
//! little-endian, there are no timestamps, and all physical section lengths
//! are derivable from the fixed header. The product parser lives separately;
//! this tool verifies every generated byte against the source model before it
//! writes either output.

use figrid_board::codebook_eval::CodebookWeights;
use figrid_board::pattern_table::{PATTERN_NUM_IDS, PATTERN_RARE_ID};
use std::env;
use std::fs;
use std::path::{Path, PathBuf};

const MAGIC: &[u8; 8] = b"NORUCBF1";
const VERSION: u16 = 1;
const HEADER_LEN: usize = 96;
const REGIONS: usize = 9;
const CLASS_COUNT: usize = 5;
const FIXED_TOKEN: usize = 585;
const TOPK_BYTES: &[u8] = include_bytes!("../data/topk.bin");

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u16)]
enum ArtifactKind {
    CompactFlat = 0,
    Factored = 1,
}

impl ArtifactKind {
    fn from_u16(value: u16) -> Result<Self, String> {
        match value {
            0 => Ok(Self::CompactFlat),
            1 => Ok(Self::Factored),
            _ => Err(format!("unsupported artifact kind: {value}")),
        }
    }
}

struct FactoredEmbeddings {
    class_map: Vec<u8>,
    bases: Vec<i16>,
    residuals: Vec<i8>,
}

fn main() {
    if let Err(error) = run() {
        eprintln!("cb-f1-pack: {error}");
        std::process::exit(2);
    }
}

fn run() -> Result<(), String> {
    let args: Vec<_> = env::args_os().collect();
    if args.len() != 5 {
        return Err(format!(
            "usage: {} <input.json> <source-sha256-hex> <compact-flat.cbf> <factored.cbf>",
            args.first()
                .map(|value| value.to_string_lossy())
                .unwrap_or_else(|| "cb-f1-pack".into())
        ));
    }

    let input = PathBuf::from(&args[1]);
    let expected_source_sha = parse_hex_sha256(&args[2].to_string_lossy())?;
    let flat_output = PathBuf::from(&args[3]);
    let factored_output = PathBuf::from(&args[4]);
    validate_distinct_paths(&input, &flat_output, &factored_output)?;

    let source =
        fs::read(&input).map_err(|error| format!("failed to read {}: {error}", input.display()))?;
    let actual_source_sha = sha256(&source);
    if actual_source_sha != expected_source_sha {
        return Err(format!(
            "source SHA-256 mismatch: expected {}, got {}",
            hex_sha256(&expected_source_sha),
            hex_sha256(&actual_source_sha)
        ));
    }

    let weights = CodebookWeights::from_json_bytes(&source)?;
    validate_model_shape(&weights)?;
    let quantized = weights.quantize_i16_s32_s64();
    if quantized.bias.to_bits() != weights.bias.to_bits() {
        return Err("quantizer changed the shared bias bits".to_string());
    }

    let factored = factor_embeddings(&quantized.embeddings, weights.dim)?;
    let flat = build_artifact(
        ArtifactKind::CompactFlat,
        &weights,
        &quantized,
        expected_source_sha,
        None,
    )?;
    let factored_bytes = build_artifact(
        ArtifactKind::Factored,
        &weights,
        &quantized,
        expected_source_sha,
        Some(&factored),
    )?;

    audit_artifact(
        &flat,
        ArtifactKind::CompactFlat,
        &weights,
        &quantized,
        expected_source_sha,
    )?;
    audit_artifact(
        &factored_bytes,
        ArtifactKind::Factored,
        &weights,
        &quantized,
        expected_source_sha,
    )?;

    ensure_parent(&flat_output)?;
    ensure_parent(&factored_output)?;
    fs::write(&flat_output, &flat)
        .map_err(|error| format!("failed to write {}: {error}", flat_output.display()))?;
    fs::write(&factored_output, &factored_bytes)
        .map_err(|error| format!("failed to write {}: {error}", factored_output.display()))?;

    println!(
        "compact-flat path={} bytes={} sha256={}",
        flat_output.display(),
        flat.len(),
        hex_sha256(&sha256(&flat))
    );
    println!(
        "factored path={} bytes={} sha256={}",
        factored_output.display(),
        factored_bytes.len(),
        hex_sha256(&sha256(&factored_bytes))
    );
    println!(
        "factored-delta bytes={} percent={:.6}",
        flat.len() as i64 - factored_bytes.len() as i64,
        100.0 * (flat.len() - factored_bytes.len()) as f64 / flat.len() as f64
    );
    Ok(())
}

fn validate_distinct_paths(input: &Path, flat: &Path, factored: &Path) -> Result<(), String> {
    if input == flat || input == factored || flat == factored {
        return Err("input, compact-flat output, and factored output must be distinct".to_string());
    }
    Ok(())
}

fn ensure_parent(path: &Path) -> Result<(), String> {
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        fs::create_dir_all(parent)
            .map_err(|error| format!("failed to create {}: {error}", parent.display()))?;
    }
    Ok(())
}

fn validate_model_shape(weights: &CodebookWeights) -> Result<(), String> {
    if weights.dim == 0 || weights.dim > u16::MAX as usize {
        return Err(format!("unsupported embedding dimension: {}", weights.dim));
    }
    if weights.fm_rank == 0 || weights.fm_rank > u16::MAX as usize {
        return Err(format!("unsupported FM rank: {}", weights.fm_rank));
    }
    if PATTERN_NUM_IDS > u16::MAX as usize {
        return Err(format!("token count does not fit u16: {PATTERN_NUM_IDS}"));
    }
    if weights.embeddings.len() != PATTERN_NUM_IDS * weights.dim {
        return Err(format!(
            "embedding count mismatch: got {}, expected {}",
            weights.embeddings.len(),
            PATTERN_NUM_IDS * weights.dim
        ));
    }
    if weights.head.len() != REGIONS * weights.dim {
        return Err(format!(
            "head count mismatch: got {}, expected {}",
            weights.head.len(),
            REGIONS * weights.dim
        ));
    }
    if weights.factors.len() != weights.head.len() * weights.fm_rank {
        return Err(format!(
            "factor count mismatch: got {}, expected {}",
            weights.factors.len(),
            weights.head.len() * weights.fm_rank
        ));
    }
    if TOPK_BYTES.len() != (PATTERN_NUM_IDS - 1) * 4 {
        return Err(format!(
            "topk.bin length mismatch: got {}, expected {}",
            TOPK_BYTES.len(),
            (PATTERN_NUM_IDS - 1) * 4
        ));
    }
    Ok(())
}

fn factor_embeddings(flat: &[i16], dim: usize) -> Result<FactoredEmbeddings, String> {
    if flat.len() != PATTERN_NUM_IDS * dim {
        return Err("flat embedding length does not match token count and dimension".to_string());
    }

    let class_map = build_class_map()?;
    let mut minima = vec![i16::MAX; CLASS_COUNT * dim];
    let mut maxima = vec![i16::MIN; CLASS_COUNT * dim];
    let mut class_sizes = [0usize; CLASS_COUNT];

    for token in 0..PATTERN_NUM_IDS {
        let class = class_map[token] as usize;
        class_sizes[class] += 1;
        for component in 0..dim {
            let value = flat[token * dim + component];
            let slot = class * dim + component;
            minima[slot] = minima[slot].min(value);
            maxima[slot] = maxima[slot].max(value);
        }
    }
    if let Some(class) = class_sizes.iter().position(|&size| size == 0) {
        return Err(format!("factored class {class} is empty"));
    }

    let mut bases = Vec::with_capacity(CLASS_COUNT * dim);
    for (&minimum, &maximum) in minima.iter().zip(&maxima) {
        let range = maximum as i32 - minimum as i32;
        let base = minimum as i32 + (range + 1) / 2;
        bases.push(
            i16::try_from(base)
                .map_err(|_| format!("ceil-midpoint base does not fit i16: {base}"))?,
        );
    }

    let mut residuals = Vec::with_capacity(flat.len());
    for token in 0..PATTERN_NUM_IDS {
        let class = class_map[token] as usize;
        for component in 0..dim {
            let value = flat[token * dim + component] as i32;
            let base = bases[class * dim + component] as i32;
            let residual = value - base;
            residuals.push(i8::try_from(residual).map_err(|_| {
                format!(
                    "residual does not fit i8: token={token} component={component} \
                     class={class} value={value} base={base} residual={residual}"
                )
            })?);
        }
    }

    Ok(FactoredEmbeddings {
        class_map,
        bases,
        residuals,
    })
}

fn build_class_map() -> Result<Vec<u8>, String> {
    let mut classes = Vec::with_capacity(PATTERN_NUM_IDS);
    for token in 0..PATTERN_NUM_IDS {
        let class = if token == FIXED_TOKEN {
            4
        } else if token == PATTERN_RARE_ID as usize {
            3
        } else {
            let offset = token * 4;
            let packed = u32::from_le_bytes(
                TOPK_BYTES[offset..offset + 4]
                    .try_into()
                    .expect("four-byte top-K record"),
            );
            // pack_window stores index 5 at bits 10..11.
            let center = ((packed >> 10) & 0b11) as u8;
            if center > 2 {
                return Err(format!(
                    "top-K token {token} has impossible boundary anchor class {center}"
                ));
            }
            center
        };
        classes.push(class);
    }
    Ok(classes)
}

fn build_artifact(
    kind: ArtifactKind,
    weights: &CodebookWeights,
    quantized: &figrid_board::codebook_eval::QuantizedCodebookWeights,
    source_sha: [u8; 32],
    factored: Option<&FactoredEmbeddings>,
) -> Result<Vec<u8>, String> {
    match (kind, factored) {
        (ArtifactKind::CompactFlat, None) | (ArtifactKind::Factored, Some(_)) => {}
        _ => return Err("artifact kind and embedding representation disagree".to_string()),
    }

    let mut payload = Vec::new();
    append_f32_slice(&mut payload, &weights.embeddings);
    append_f32_slice(&mut payload, &weights.head);
    append_f32_slice(&mut payload, &weights.factors);
    payload.extend_from_slice(&weights.bias.to_bits().to_le_bytes());

    let class_count = match kind {
        ArtifactKind::CompactFlat => {
            append_i16_slice(&mut payload, &quantized.embeddings);
            0
        }
        ArtifactKind::Factored => {
            let factored = factored.expect("validated factored representation");
            payload.extend_from_slice(&factored.class_map);
            append_i16_slice(&mut payload, &factored.bases);
            payload.extend(factored.residuals.iter().map(|&value| value as u8));
            CLASS_COUNT
        }
    };
    append_i16_slice(&mut payload, &quantized.head);
    append_i16_slice(&mut payload, &quantized.factors);

    let payload_len = u32::try_from(payload.len())
        .map_err(|_| format!("payload is too large: {} bytes", payload.len()))?;
    let mut output = vec![0u8; HEADER_LEN];
    output[0..8].copy_from_slice(MAGIC);
    put_u16(&mut output, 8, VERSION);
    put_u16(&mut output, 10, kind as u16);
    put_u16(&mut output, 12, weights.dim as u16);
    put_u16(&mut output, 14, weights.fm_rank as u16);
    put_u16(&mut output, 16, REGIONS as u16);
    put_u16(&mut output, 18, PATTERN_NUM_IDS as u16);
    put_u16(&mut output, 20, class_count as u16);
    put_u16(&mut output, 22, 0);
    put_i32(&mut output, 24, quantized.embedding_scale);
    put_i32(&mut output, 28, quantized.head_scale);
    put_i32(&mut output, 32, quantized.factor_scale);
    put_u32(
        &mut output,
        36,
        checked_u32(weights.embeddings.len(), "embeddings")?,
    );
    put_u32(&mut output, 40, checked_u32(weights.head.len(), "head")?);
    put_u32(
        &mut output,
        44,
        checked_u32(weights.factors.len(), "factors")?,
    );
    // This is the logical reconstructed N*D count for both representations.
    put_u32(
        &mut output,
        48,
        checked_u32(quantized.embeddings.len(), "quantized embeddings")?,
    );
    put_u32(&mut output, 52, payload_len);
    output[56..88].copy_from_slice(&source_sha);
    // 88..96 remains zero.
    output.extend_from_slice(&payload);
    Ok(output)
}

fn audit_artifact(
    artifact: &[u8],
    expected_kind: ArtifactKind,
    weights: &CodebookWeights,
    quantized: &figrid_board::codebook_eval::QuantizedCodebookWeights,
    source_sha: [u8; 32],
) -> Result<(), String> {
    if artifact.len() < HEADER_LEN {
        return Err("artifact is shorter than its header".to_string());
    }
    if &artifact[0..8] != MAGIC {
        return Err("artifact magic mismatch".to_string());
    }
    if read_u16(artifact, 8)? != VERSION {
        return Err("artifact version mismatch".to_string());
    }
    let kind = ArtifactKind::from_u16(read_u16(artifact, 10)?)?;
    if kind != expected_kind {
        return Err("artifact kind mismatch".to_string());
    }
    if read_u16(artifact, 12)? as usize != weights.dim
        || read_u16(artifact, 14)? as usize != weights.fm_rank
        || read_u16(artifact, 16)? as usize != REGIONS
        || read_u16(artifact, 18)? as usize != PATTERN_NUM_IDS
    {
        return Err("artifact dimensions mismatch".to_string());
    }
    let expected_classes = match kind {
        ArtifactKind::CompactFlat => 0,
        ArtifactKind::Factored => CLASS_COUNT,
    };
    if read_u16(artifact, 20)? as usize != expected_classes
        || read_u16(artifact, 22)? != 0
        || artifact[88..96].iter().any(|&byte| byte != 0)
    {
        return Err("artifact class count or reserved fields mismatch".to_string());
    }
    if read_i32(artifact, 24)? != quantized.embedding_scale
        || read_i32(artifact, 28)? != quantized.head_scale
        || read_i32(artifact, 32)? != quantized.factor_scale
    {
        return Err("artifact quantization scale mismatch".to_string());
    }
    if read_u32(artifact, 36)? as usize != weights.embeddings.len()
        || read_u32(artifact, 40)? as usize != weights.head.len()
        || read_u32(artifact, 44)? as usize != weights.factors.len()
        || read_u32(artifact, 48)? as usize != quantized.embeddings.len()
    {
        return Err("artifact element count mismatch".to_string());
    }
    let payload_len = read_u32(artifact, 52)? as usize;
    if artifact.len() != HEADER_LEN + payload_len {
        return Err(format!(
            "artifact payload length mismatch: header={payload_len}, actual={}",
            artifact.len() - HEADER_LEN
        ));
    }
    if artifact[56..88] != source_sha {
        return Err("artifact source SHA-256 mismatch".to_string());
    }

    let mut cursor = Cursor::new(&artifact[HEADER_LEN..]);
    audit_f32_slice(&mut cursor, &weights.embeddings, "source embeddings")?;
    audit_f32_slice(&mut cursor, &weights.head, "source head")?;
    audit_f32_slice(&mut cursor, &weights.factors, "source factors")?;
    if cursor.f32_bits()? != weights.bias.to_bits() {
        return Err("source bias bits mismatch".to_string());
    }

    match kind {
        ArtifactKind::CompactFlat => {
            audit_i16_slice(&mut cursor, &quantized.embeddings, "flat embeddings")?;
        }
        ArtifactKind::Factored => {
            let classes = cursor.take(PATTERN_NUM_IDS)?.to_vec();
            if classes.iter().any(|&class| class as usize >= CLASS_COUNT) {
                return Err("factored artifact contains an out-of-range class".to_string());
            }
            if classes != build_class_map()? {
                return Err("factored artifact class map mismatch".to_string());
            }
            let bases = cursor.i16_vec(CLASS_COUNT * weights.dim)?;
            let residual_bytes = cursor.take(PATTERN_NUM_IDS * weights.dim)?;
            for token in 0..PATTERN_NUM_IDS {
                let class = classes[token] as usize;
                for component in 0..weights.dim {
                    let base = bases[class * weights.dim + component] as i32;
                    let residual = residual_bytes[token * weights.dim + component] as i8 as i32;
                    let reconstructed = base + residual;
                    let expected = quantized.embeddings[token * weights.dim + component] as i32;
                    if reconstructed != expected {
                        return Err(format!(
                            "factored reconstruction mismatch: token={token} \
                             component={component} got={reconstructed} expected={expected}"
                        ));
                    }
                    i16::try_from(reconstructed).map_err(|_| {
                        format!(
                            "factored reconstruction overflows i16: token={token} \
                             component={component} value={reconstructed}"
                        )
                    })?;
                }
            }
        }
    }
    audit_i16_slice(&mut cursor, &quantized.head, "quantized head")?;
    audit_i16_slice(&mut cursor, &quantized.factors, "quantized factors")?;
    if cursor.remaining() != 0 {
        return Err(format!(
            "artifact has {} unexpected trailing payload bytes",
            cursor.remaining()
        ));
    }
    Ok(())
}

fn append_f32_slice(output: &mut Vec<u8>, values: &[f32]) {
    for value in values {
        output.extend_from_slice(&value.to_bits().to_le_bytes());
    }
}

fn append_i16_slice(output: &mut Vec<u8>, values: &[i16]) {
    for value in values {
        output.extend_from_slice(&value.to_le_bytes());
    }
}

fn audit_f32_slice(cursor: &mut Cursor<'_>, expected: &[f32], label: &str) -> Result<(), String> {
    for (index, value) in expected.iter().enumerate() {
        let got = cursor.f32_bits()?;
        if got != value.to_bits() {
            return Err(format!("{label} bit mismatch at {index}"));
        }
    }
    Ok(())
}

fn audit_i16_slice(cursor: &mut Cursor<'_>, expected: &[i16], label: &str) -> Result<(), String> {
    for (index, &value) in expected.iter().enumerate() {
        let got = cursor.i16()?;
        if got != value {
            return Err(format!(
                "{label} mismatch at {index}: got {got}, expected {value}"
            ));
        }
    }
    Ok(())
}

fn checked_u32(value: usize, label: &str) -> Result<u32, String> {
    u32::try_from(value).map_err(|_| format!("{label} count does not fit u32: {value}"))
}

fn put_u16(output: &mut [u8], offset: usize, value: u16) {
    output[offset..offset + 2].copy_from_slice(&value.to_le_bytes());
}

fn put_i32(output: &mut [u8], offset: usize, value: i32) {
    output[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
}

fn put_u32(output: &mut [u8], offset: usize, value: u32) {
    output[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
}

fn read_u16(input: &[u8], offset: usize) -> Result<u16, String> {
    let bytes: [u8; 2] = input
        .get(offset..offset + 2)
        .ok_or_else(|| "truncated u16 field".to_string())?
        .try_into()
        .expect("two-byte slice");
    Ok(u16::from_le_bytes(bytes))
}

fn read_i32(input: &[u8], offset: usize) -> Result<i32, String> {
    let bytes: [u8; 4] = input
        .get(offset..offset + 4)
        .ok_or_else(|| "truncated i32 field".to_string())?
        .try_into()
        .expect("four-byte slice");
    Ok(i32::from_le_bytes(bytes))
}

fn read_u32(input: &[u8], offset: usize) -> Result<u32, String> {
    let bytes: [u8; 4] = input
        .get(offset..offset + 4)
        .ok_or_else(|| "truncated u32 field".to_string())?
        .try_into()
        .expect("four-byte slice");
    Ok(u32::from_le_bytes(bytes))
}

struct Cursor<'a> {
    bytes: &'a [u8],
    offset: usize,
}

impl<'a> Cursor<'a> {
    fn new(bytes: &'a [u8]) -> Self {
        Self { bytes, offset: 0 }
    }

    fn take(&mut self, count: usize) -> Result<&'a [u8], String> {
        let end = self
            .offset
            .checked_add(count)
            .ok_or_else(|| "payload cursor overflow".to_string())?;
        let slice = self
            .bytes
            .get(self.offset..end)
            .ok_or_else(|| "artifact payload is truncated".to_string())?;
        self.offset = end;
        Ok(slice)
    }

    fn i16(&mut self) -> Result<i16, String> {
        let bytes: [u8; 2] = self.take(2)?.try_into().expect("two-byte slice");
        Ok(i16::from_le_bytes(bytes))
    }

    fn i16_vec(&mut self, count: usize) -> Result<Vec<i16>, String> {
        (0..count).map(|_| self.i16()).collect()
    }

    fn f32_bits(&mut self) -> Result<u32, String> {
        let bytes: [u8; 4] = self.take(4)?.try_into().expect("four-byte slice");
        Ok(u32::from_le_bytes(bytes))
    }

    fn remaining(&self) -> usize {
        self.bytes.len() - self.offset
    }
}

fn parse_hex_sha256(value: &str) -> Result<[u8; 32], String> {
    if value.len() != 64 {
        return Err(format!(
            "source SHA-256 must contain exactly 64 hex digits, got {}",
            value.len()
        ));
    }
    let mut output = [0u8; 32];
    let bytes = value.as_bytes();
    for index in 0..32 {
        output[index] = (hex_nibble(bytes[index * 2])? << 4) | hex_nibble(bytes[index * 2 + 1])?;
    }
    Ok(output)
}

fn hex_nibble(value: u8) -> Result<u8, String> {
    match value {
        b'0'..=b'9' => Ok(value - b'0'),
        b'a'..=b'f' => Ok(value - b'a' + 10),
        b'A'..=b'F' => Ok(value - b'A' + 10),
        _ => Err(format!("invalid hex digit: {:?}", value as char)),
    }
}

fn hex_sha256(value: &[u8; 32]) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut output = String::with_capacity(64);
    for &byte in value {
        output.push(HEX[(byte >> 4) as usize] as char);
        output.push(HEX[(byte & 0x0f) as usize] as char);
    }
    output
}

fn sha256(input: &[u8]) -> [u8; 32] {
    const INITIAL: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
        0x5be0cd19,
    ];
    const K: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4,
        0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,
        0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
        0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
        0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
        0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
        0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116,
        0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
        0xc67178f2,
    ];

    let bit_len = (input.len() as u64).wrapping_mul(8);
    let mut padded = Vec::with_capacity((input.len() + 72) & !63);
    padded.extend_from_slice(input);
    padded.push(0x80);
    while padded.len() % 64 != 56 {
        padded.push(0);
    }
    padded.extend_from_slice(&bit_len.to_be_bytes());

    let mut state = INITIAL;
    let mut words = [0u32; 64];
    for chunk in padded.chunks_exact(64) {
        for (index, word) in words.iter_mut().take(16).enumerate() {
            *word = u32::from_be_bytes(
                chunk[index * 4..index * 4 + 4]
                    .try_into()
                    .expect("four-byte SHA-256 word"),
            );
        }
        for index in 16..64 {
            let s0 = words[index - 15].rotate_right(7)
                ^ words[index - 15].rotate_right(18)
                ^ (words[index - 15] >> 3);
            let s1 = words[index - 2].rotate_right(17)
                ^ words[index - 2].rotate_right(19)
                ^ (words[index - 2] >> 10);
            words[index] = words[index - 16]
                .wrapping_add(s0)
                .wrapping_add(words[index - 7])
                .wrapping_add(s1);
        }

        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut h] = state;
        for index in 0..64 {
            let big_s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let choose = (e & f) ^ ((!e) & g);
            let temp1 = h
                .wrapping_add(big_s1)
                .wrapping_add(choose)
                .wrapping_add(K[index])
                .wrapping_add(words[index]);
            let big_s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let majority = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = big_s0.wrapping_add(majority);

            h = g;
            g = f;
            f = e;
            e = d.wrapping_add(temp1);
            d = c;
            c = b;
            b = a;
            a = temp1.wrapping_add(temp2);
        }
        for (value, addend) in state.iter_mut().zip([a, b, c, d, e, f, g, h]) {
            *value = value.wrapping_add(addend);
        }
    }

    let mut digest = [0u8; 32];
    for (index, value) in state.iter().enumerate() {
        digest[index * 4..index * 4 + 4].copy_from_slice(&value.to_be_bytes());
    }
    digest
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sha256_known_vectors() {
        assert_eq!(
            hex_sha256(&sha256(b"")),
            "E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"
        );
        assert_eq!(
            hex_sha256(&sha256(b"abc")),
            "BA7816BF8F01CFEA414140DE5DAE2223B00361A396177A9CB410FF61F20015AD"
        );
    }

    #[test]
    fn class_map_has_frozen_semantic_counts() {
        let classes = build_class_map().expect("class map");
        let mut counts = [0usize; CLASS_COUNT];
        for class in classes {
            counts[class as usize] += 1;
        }
        // The census's semantic classes are [2019, 1123, 1123, 1] before
        // token 585 (anchor empty) is split into its singleton fifth class.
        assert_eq!(counts, [2018, 1123, 1123, 1, 1]);
        assert_eq!(build_class_map().unwrap()[FIXED_TOKEN], 4);
        assert_eq!(build_class_map().unwrap()[PATTERN_RARE_ID as usize], 3);
    }
}
